/* Interactive learning layer. Original guides and source tests remain separate. */
const JOURNEY_KEY='holusCounselingJourneysV1';
let journeyStorageAvailable=true;
let journeyStore;try{journeyStore=JSON.parse(localStorage.getItem(JOURNEY_KEY)||'{}')}catch{journeyStore={};journeyStorageAvailable=false};
if(!journeyStore||typeof journeyStore!=='object'||Array.isArray(journeyStore))journeyStore={};
function journeySave(){try{localStorage.setItem(JOURNEY_KEY,JSON.stringify(journeyStore));journeyStorageAvailable=true;return true}catch{journeyStorageAvailable=false;return false}}
function journeyState(id){if(!journeyStore[id]||typeof journeyStore[id]!=='object'||Array.isArray(journeyStore[id]))journeyStore[id]={};const s=journeyStore[id];s.position=Number.isInteger(s.position)?s.position:0;s.responses=s.responses&&typeof s.responses==='object'&&!Array.isArray(s.responses)?s.responses:{};s.confidence=s.confidence&&typeof s.confidence==='object'&&!Array.isArray(s.confidence)?s.confidence:{};s.launched=Boolean(s.launched);return s}
function journeyData(id){return (window.NC_JOURNEYS||{})[id]}
function journeyResponse(id,step){const s=journeyState(id);if(!s.responses[step.id]||typeof s.responses[step.id]!=='object'||Array.isArray(s.responses[step.id]))s.responses[step.id]={};return s.responses[step.id]}
function journeyCompleted(steps,s){return steps.filter(st=>s.responses[st.id]?.done).length}
function journeyText(text){return `<p>${esc(text)}</p>`}
function genericJourneyBlueprint(data){
 const steps=data.steps||[],groups=[];
 for(let i=0;i<steps.length;i+=2){const chunk=steps.slice(i,i+2);groups.push({id:`part-${groups.length+1}`,label:`Part ${groups.length+1}`,title:chunk[0]?.title||`Learning part ${groups.length+1}`,stepIds:chunk.map(x=>x.id),summary:chunk.map(x=>x.title).join(' · '),highlight:chunk[0]?.teach?.[0]?.split(/(?<=[.!?])\s/)[0]||data.kicker})}
 return {duration:`${Math.max(25,steps.length*4)}–${Math.max(35,steps.length*5)} minutes`,level:'Guided independent study',why:data.practice?.takeaway?.replace(/^What this means for my practice:\s*/i,'')||data.kicker,outcomes:steps.slice(0,4).map(x=>`Explain and apply: ${x.title}.`),order:steps.map(x=>x.id),modules:groups,stepHighlights:{},recap:steps.slice(0,5).map(x=>x.title)}
}
function journeyBlueprint(id,data){const authored=(window.NC_LEARNING_BLUEPRINTS||{})[id];return authored||genericJourneyBlueprint(data)}
function orderedJourneySteps(data,blueprint,id){
 const byId=new Map(data.steps.map(x=>[x.id,x]));
 if(Array.isArray(blueprint.integratedSteps)&&blueprint.integratedSteps.length)return blueprint.integratedSteps.map(plan=>{const activity=byId.get(plan.activityId);return {...(activity||{}),...plan,type:activity?.type||'review',teach:activity?.teach||[]}});
 const ordered=(blueprint.order||[]).map(stepId=>byId.get(stepId)).filter(Boolean);for(const step of data.steps)if(!ordered.includes(step))ordered.push(step);return ordered
}
function journeyGuideSections(id,step){const byId=new Map((STUDY_GUIDES[id]?.sections||[]).map(section=>[section.id,section]));return (step.sectionIds||[]).map(sectionId=>byId.get(sectionId)).filter(Boolean)}
function journeyModule(blueprint,step){return blueprint.modules.find(module=>module.stepIds.includes(step?.id))||blueprint.modules[0]}
function journeyFirstIncomplete(steps,s){const index=steps.findIndex(step=>!s.responses[step.id]?.done);return index<0?Math.min(s.position,steps.length):index}
function journeyHighlight(blueprint,module,step){return step.keyIdea||blueprint.stepHighlights?.[step.id]||step.teach?.[0]?.split(/(?<=[.!?])\s/)[0]||module?.highlight||''}
function renderJourneyLaunch(id,data,s,blueprint,steps){
 const stage=COURSE_STAGES.find(x=>x.id===id),completed=journeyCompleted(steps,s),resume=completed>0,integrated=Array.isArray(blueprint.integratedSteps);
 const method=integrated?'The comprehensive teaching is inside the learning path. Each focused knowledge chunk is followed by retrieval, a decision, a calculation or a scenario with explanatory feedback.':'This lesson already uses the same guided rhythm. Verified comprehensive content will expand inside this path as it is added, without creating a separate notes detour.';
 const scope=integrated?'The teaching, worked examples, cautions and practice implications are integrated into each step. Source links support the lesson; assigned textbook chapters and official answer keys remain separate unless supplied.':'This guided path currently organizes the available teaching and practice. New verified content can be added directly to these learning moments while the supplied source test remains separate.';
 return `<section class="view journey-view learning-launch"><header class="learning-launch-hero"><div><p class="eyebrow">Lesson ${stage.number} · Guided eLearning</p><h1>${esc(data.title)}</h1><p class="lede">${esc(blueprint.why)}</p><div class="learning-meta"><span>${esc(blueprint.duration)}</span><span>${esc(blueprint.level||'Guided independent study')}</span><span>${blueprint.modules.length} learning modules</span></div><div class="learning-launch-actions"><button class="primary" type="button" data-j-launch>${resume?'Resume my learning':'Begin the lesson'} →</button></div></div><aside class="learning-launch-card"><span>How this lesson works</span><strong>Understand it. Use it. Explain it.</strong><p>${esc(method)}</p><div class="learning-rhythm"><span>Orient</span><span>Learn</span><span>Apply</span><span>Reflect</span></div></aside></header><section class="learning-outcomes" aria-labelledby="learning-outcomes-title"><div><p class="eyebrow">Learning outcomes</p><h2 id="learning-outcomes-title">By the end, you will be able to…</h2><p>${integrated?'These outcomes organize the substantial knowledge into decisions you can retrieve and apply.':'These outcomes organize the current teaching into ideas you can retrieve and apply.'}</p></div><ol>${blueprint.outcomes.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></section><section class="learning-modules" aria-labelledby="learning-modules-title"><p class="eyebrow">Your route</p><h2 id="learning-modules-title">${blueprint.modules.length} purposeful modules—not a long information dump.</h2><div class="learning-module-grid">${blueprint.modules.map(module=>`<article class="learning-module-card"><b>${esc(module.label)}</b><strong>${esc(module.title)}</strong><p>${esc(module.summary)}</p></article>`).join('')}</div></section><details class="journey-boundary"><summary>Evidence and learning scope</summary><p>${esc(scope)}</p></details>${footer()}</section>`
}
function journeySyncPosition(steps,s){if(s.orderVersion===3){const saved=s.stepId==='__consolidate__'?steps.length:steps.findIndex(step=>step.id===s.stepId);s.position=saved>=0?saved:journeyFirstIncomplete(steps,s)}else s.position=journeyFirstIncomplete(steps,s);s.position=Math.max(0,Math.min(steps.length,s.position));s.stepId=steps[s.position]?.id||'__consolidate__';s.orderVersion=3}
function renderJourneyMap(blueprint,steps,s,idx,final){
 const modules=blueprint.modules.map(module=>{const indexes=module.stepIds.map(id=>steps.findIndex(step=>step.id===id)).filter(i=>i>=0),done=indexes.filter(i=>s.responses[steps[i].id]?.done).length,active=!final&&indexes.includes(idx),start=indexes[0]??0;return `<button type="button" data-j-module="${start}" class="${active?'active':''}" ${active?'aria-current="step"':''}><b>${esc(module.label)}</b><small>${esc(module.title)}</small><em>${done} / ${indexes.length} activities</em></button>`}).join('');
 return `<nav class="journey-map" aria-label="Learning modules">${modules}<button type="button" data-j-module="${steps.length}" class="${final?'active':''}" ${final?'aria-current="step"':''}><b>Consolidate</b><small>Apply, reflect and recap</small><em>${s.finished?'Finished':'Final learning step'}</em></button></nav>`
}
function renderJourneyActivity(id,step){
 const r=journeyResponse(id,step);let body='';
 if(step.type==='review'){
 body=`<div class="journey-retrieval"><p>Answer aloud or in your notes before comparing.</p><button type="button" class="primary" data-j-review aria-expanded="${Boolean(r.revealed)}">${r.revealed?'Key idea revealed':'Compare with the key idea'}</button>${r.revealed?`<div class="journey-feedback" role="status"><strong>Key idea</strong>${journeyText(step.keyIdea)}</div>`:''}</div>`;
 } else if(step.type==='choice'){
 body=`<div class="journey-options" role="group" aria-label="Choose an approach">${step.options.map((o,i)=>`<button type="button" class="journey-option ${r.choice===i?'chosen':''}" data-j-choice="${i}" aria-pressed="${r.choice===i}"><span>${String.fromCharCode(65+i)}</span>${esc(o.label)}</button>`).join('')}</div>`;
 if(Number.isInteger(r.choice)&&step.options[r.choice]){const o=step.options[r.choice];body+=`<div class="journey-feedback ${o.correct?'helpful':'rethink'}" role="status"><strong>${o.correct?'That approach fits':'Consider another approach'}</strong>${journeyText(o.feedback)}<small>You can try another option to compare the reasoning.</small></div>`}
 } else if(step.type==='explore'){
 body=`<div class="journey-explore" role="group" aria-label="Explore the examples">${step.panels.map((p,i)=>`<button type="button" data-j-panel="${i}" aria-pressed="${r.panel===i}" class="${r.panel===i?'chosen':''}">${esc(p.label)} ${(Array.isArray(r.seen)&&r.seen.includes(i))?'<span aria-label="explored">✓</span>':''}</button>`).join('')}</div>`;
 body+=Number.isInteger(r.panel)&&step.panels[r.panel]?`<div class="journey-feedback" role="status"><strong>${esc(step.panels[r.panel].label)}</strong>${journeyText(step.panels[r.panel].text)}</div>`:'<p class="journey-hint">Make a prediction, then tap each example to explore what changes.</p>';
 } else if(step.type==='sort'){
 body=`<div class="journey-sort">${step.items.map((item,i)=>`<div class="journey-sort-row"><label for="j-sort-${i}">${esc(item.label)}</label><select id="j-sort-${i}" data-j-sort="${i}"><option value="">Choose a category…</option>${step.categories.map((c,k)=>`<option value="${k}" ${r.sort?.[i]===k?'selected':''}>${esc(c)}</option>`).join('')}</select>${r.checked?`<p class="sort-feedback"><strong>${r.sort?.[i]===item.category?'✓ Fits':'Revisit: '+esc(step.categories[item.category])}</strong> ${esc(item.feedback)}</p>`:''}</div>`).join('')}</div><button type="button" class="primary" data-j-check-sort>Check my sorting</button><div class="journey-feedback" data-j-status role="status">${r.checked?'Compare the explanations above. You can change your choices and check again.':''}</div>`;
 } else if(step.type==='number'){
 body=`<form data-j-number-form><label class="journey-number-label" for="j-number">Your estimate${step.unit?' ('+esc(step.unit)+')':''}</label><div class="journey-number"><input id="j-number" name="answer" type="number" inputmode="decimal" step="any" required value="${esc(r.input??'')}" aria-describedby="j-number-status"><button class="primary" type="submit">Check & explain</button></div></form><div class="journey-feedback" id="j-number-status" role="status">${r.checked?`<strong>${Math.abs(Number(r.input)-step.answer)<=step.tolerance?'Your calculation fits':'Let’s work through it'}</strong><p>${esc(step.explanation)}</p>`:''}</div>`;
 }
 return `<section class="journey-activity" aria-labelledby="activity-title"><p class="eyebrow">Apply it · ${({review:'Retrieve the essential point',choice:'Make a decision',explore:'Explore the contrast',sort:'Sort the ideas',number:'Work it out'})[step.type]}</p><h3 id="activity-title">${esc(step.prompt)}</h3>${body}</section>`;
}
function renderJourney(id){
 const data=journeyData(id),s=journeyState(id),blueprint=journeyBlueprint(id,data),steps=orderedJourneySteps(data,blueprint,id),n=steps.length;journeySyncPosition(steps,s);
 if(!s.launched)return renderJourneyLaunch(id,data,s,blueprint,steps);
 s.position=Math.max(0,Math.min(n,s.position));const idx=s.position,final=idx===n,stage=COURSE_STAGES.find(x=>x.id===id),completed=journeyCompleted(steps,s),step=steps[idx],module=journeyModule(blueprint,step),moduleSteps=module?module.stepIds.filter(stepId=>steps.some(x=>x.id===stepId)):[],moduleIndex=step&&module?moduleSteps.indexOf(step.id):-1,knowledgeSections=final?[]:journeyGuideSections(id,step);
 const knowledge=knowledgeSections.length?`<div class="journey-knowledge">${knowledgeSections.map((section,i)=>`<section class="journey-knowledge-section"><p class="eyebrow">Substantial knowledge · ${i+1} of ${knowledgeSections.length}</p><h3>${esc(section.title.replace(/^\d+[.]?\s*/,''))}</h3><div class="journey-knowledge-body">${section.html}</div></section>`).join('')}</div>`:(step?.teach||[]).map(journeyText).join('');
 return `<section class="view journey-view"><header class="journey-hero"><div><p class="eyebrow">Lesson ${stage.number} · Guided eLearning</p><h1>${esc(data.title)}</h1><p class="lede">${esc(data.kicker.split(" • ")[0])}</p></div><div class="learning-launch-actions"><button class="secondary" type="button" data-j-home>Lesson overview</button></div></header><div class="journey-progress"><span><strong>${completed} of ${n}</strong> learning moments completed <small>· progress, not an exam score</small></span><progress max="${n}" value="${completed}" aria-label="${completed} of ${n} learning moments completed"></progress></div>${renderJourneyMap(blueprint,steps,s,idx,final)}
 ${final?renderJourneyPractice(id,data,s,blueprint):`<div class="journey-grid ${knowledgeSections.length?'journey-grid-integrated':''}"><article class="journey-teach" tabindex="-1"><span class="journey-module-label">${esc(module?.label||'Learning module')} · ${moduleIndex+1} of ${moduleSteps.length}</span><p class="eyebrow">Teach · understand the idea</p><h2>${esc(step.title)}</h2><div class="journey-essential"><span>Must remember</span><strong>${esc(journeyHighlight(blueprint,module,step))}</strong></div>${knowledge}<div class="journey-takeaway"><span aria-hidden="true">✦</span> Pause before the activity: explain the distinction in your own words, then use the feedback to refine it.</div></article><div class="journey-apply-column">${renderJourneyActivity(id,step)}<div class="journey-confidence"><strong>How ready are you to explain this without looking?</strong><div><button type="button" data-j-confidence="ready" aria-pressed="${s.confidence[step.id]==='ready'}">I can explain it</button><button type="button" data-j-confidence="revisit" aria-pressed="${s.confidence[step.id]==='revisit'}">Revisit later</button></div></div></div></div>`}
 <footer class="journey-pager"><button class="secondary" type="button" data-j-move="-1" ${idx===0?'disabled':''}>← Back</button><span>${final?'Consolidate':`${idx+1} / ${n} · ${esc(module?.title||'Learning')}`}</span>${final?`<button class="primary" type="button" data-j-finish ${completed<n?'disabled':''}>${s.finished?'Learning path finished ✓':completed<n?`Complete ${n-completed} more ${n-completed===1?'activity':'activities'} to finish`:'Finish this learning path ✓'}</button>`:`<button class="primary" type="button" data-j-move="1">${idx===n-1?'Apply and consolidate':'Continue learning'} →</button>`}</footer><p class="journey-storage" data-j-save-status>${journeyStorageAvailable?'Progress, confidence choices and reflection save in this browser on this device.':'Storage unavailable: progress is kept only while this page stays open. Copy your reflection before leaving.'}</p>${footer()}</section>`;
}
function renderJourneyPractice(id,data,s,blueprint){
 const p=data.practice,application=blueprint.application;
 return `<article class="journey-practice" tabindex="-1"><section class="learning-recap"><p class="eyebrow">Consolidate · explain without looking</p><h2>${esc(data.title)} in ${blueprint.recap.length} essential ideas</h2><div class="learning-recap-grid">${blueprint.recap.map((item,i)=>`<article><b>${i+1}</b><p>${esc(item)}</p></article>`).join('')}</div></section>${application?`<section class="learning-application"><p class="eyebrow">Application scenario</p><h3>${esc(application.title)}</h3><p class="scenario">${esc(application.scenario)}</p><div class="learning-application-grid">${application.stages.map(stage=>`<details><summary>${esc(stage.title)}</summary><div><p>${esc(stage.prompt)}</p><ul>${stage.points.map(point=>`<li>${esc(point)}</li>`).join('')}</ul></div></details>`).join('')}</div></section>`:''}<p class="eyebrow">Transfer learning to practice</p><h2>What this means for my practice</h2><p class="practice-lead">${esc(p.takeaway.replace(/^What this means for my practice:\s*/i,""))}</p><div class="practice-lens-grid">${[['Ask with curiosity',p.ask],['Put it into practice',p.try],['Know when to refer',p.refer]].map(([title,items])=>`<section><h3>${title}</h3><ul>${items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section>`).join('')}</div><div class="journey-reflection"><label for="j-reflection">${esc(p.reflection)}</label><p>Write a fictional example or your own learning intention. Do not enter identifiable client or health records here.</p><textarea id="j-reflection" rows="4" placeholder="In my future practice, I will…">${esc(s.reflection||'')}</textarea><span data-j-reflect-status role="status"></span></div><p class="scope-note">Learning support for a nutrition counsellor in training, not authority to diagnose, prescribe or replace regulated care. Work within your actual training, competence and local requirements.</p>${data.sources?.length?`<details class="journey-sources"><summary>Evidence and sources for this learning path</summary><ul>${data.sources.map(x=>`<li><a href="${esc(x.url)}" target="_blank" rel="noopener">${esc(x.label)} ↗</a></li>`).join('')}</ul></details>`:''}<div class="hero-actions"><button class="secondary" type="button" data-go="cards">Flashcard retrieval</button><button class="secondary" type="button" data-go="practice">Practice questions</button><button class="secondary" type="button" data-go="test">Source test</button></div>${s.finished?`<div class="journey-feedback" role="status"><strong>Learning path finished.</strong><p>${journeyStorageAvailable?'Your activities, confidence choices and reflection are saved on this device.':'Storage is unavailable. Your work is only in memory; copy your reflection before leaving.'} Finishing is not a clinical competency assessment.</p><div class="hero-actions">${lessonContinuation(COURSE_STAGES.find(x=>x.id===id).number)}</div></div>`:''}</article>`
}
function journeyRerender(selector='.journey-teach, .journey-practice'){rerenderActive(selector)}
function journeyMove(next){const id=currentStage().id,data=journeyData(id),s=journeyState(id),steps=orderedJourneySteps(data,journeyBlueprint(id,data),id);s.launched=true;s.position=Math.max(0,Math.min(steps.length,next));s.stepId=steps[s.position]?.id||'__consolidate__';s.orderVersion=3;journeySave();journeyRerender()}
function bindJourney(){
 if(!app.querySelector('.journey-view'))return;
 const id=currentStage().id,data=journeyData(id),s=journeyState(id),blueprint=journeyBlueprint(id,data),steps=orderedJourneySteps(data,blueprint,id),step=steps[s.position];
 app.querySelector('[data-j-launch]')?.addEventListener('click',()=>{s.launched=true;s.position=journeyFirstIncomplete(steps,s);s.stepId=steps[s.position]?.id||'__consolidate__';s.orderVersion=3;journeySave();journeyRerender('.journey-teach, .journey-practice')});
 app.querySelector('[data-j-home]')?.addEventListener('click',()=>{s.launched=false;journeySave();journeyRerender('.learning-launch-hero')});
 app.querySelectorAll('[data-j-module]').forEach(b=>b.addEventListener('click',()=>journeyMove(Number(b.dataset.jModule))));
 app.querySelectorAll('[data-j-step]').forEach(b=>b.addEventListener('click',()=>journeyMove(Number(b.dataset.jStep))));
 app.querySelectorAll('[data-j-move]').forEach(b=>b.addEventListener('click',()=>journeyMove(s.position+Number(b.dataset.jMove))));
 app.querySelectorAll('[data-j-reference]').forEach(b=>b.addEventListener('click',()=>{state.learningMode='reference';const i=studySteps(id).findIndex(x=>x.id===b.dataset.jReference);state.lessonSteps[id]=i>=0?i:0;saveState();setView('lesson')}));
 app.querySelectorAll('[data-j-confidence]').forEach(b=>b.addEventListener('click',()=>{if(!step)return;s.confidence[step.id]=b.dataset.jConfidence;journeySave();journeyRerender('.journey-confidence')}));
 app.querySelector('[data-j-review]')?.addEventListener('click',()=>{const r=journeyResponse(id,step);r.revealed=!r.revealed;r.done=true;journeySave();journeyRerender('.journey-retrieval')});
 app.querySelectorAll('[data-j-choice]').forEach(b=>b.addEventListener('click',()=>{const r=journeyResponse(id,step);r.choice=Number(b.dataset.jChoice);r.done=true;journeySave();journeyRerender('.journey-feedback')}));
 app.querySelectorAll('[data-j-panel]').forEach(b=>b.addEventListener('click',()=>{const r=journeyResponse(id,step);r.panel=Number(b.dataset.jPanel);r.seen=Array.isArray(r.seen)?[...new Set(r.seen.filter(x=>Number.isInteger(x)&&x>=0&&x<step.panels.length))]:[];if(!r.seen.includes(r.panel))r.seen.push(r.panel);r.done=r.seen.length===step.panels.length;journeySave();journeyRerender('.journey-feedback')}));
 app.querySelectorAll('[data-j-sort]').forEach(select=>select.addEventListener('change',()=>{const r=journeyResponse(id,step);r.sort=r.sort&&typeof r.sort==='object'&&!Array.isArray(r.sort)?r.sort:{};if(select.value==='')delete r.sort[select.dataset.jSort];else r.sort[select.dataset.jSort]=Number(select.value);r.checked=false;r.done=false;journeySave();journeyRerender('#'+select.id)}));
 app.querySelector('[data-j-check-sort]')?.addEventListener('click',()=>{const r=journeyResponse(id,step);if(step.items.some((x,i)=>!Number.isInteger(r.sort?.[i]))){app.querySelector('[data-j-status]').textContent='Choose a category for each item first.';return}r.checked=true;r.done=true;journeySave();journeyRerender('.journey-sort')});
 app.querySelector('[data-j-number-form]')?.addEventListener('submit',e=>{e.preventDefault();const value=app.querySelector('#j-number').value;if(value===''||!Number.isFinite(Number(value)))return;const r=journeyResponse(id,step);r.input=value;r.checked=true;r.done=true;journeySave();journeyRerender('#j-number-status')});
 app.querySelector('#j-reflection')?.addEventListener('input',e=>{s.reflection=e.target.value;const saved=journeySave();app.querySelector('[data-j-reflect-status]').textContent=saved?'Saved on this device':'Storage unavailable. Copy your reflection before leaving.'});
 app.querySelector('[data-j-finish]')?.addEventListener('click',()=>{if(journeyCompleted(steps,s)<steps.length)return;s.finished=true;journeySave();journeyRerender('.journey-practice')});
}
